const $=s=>document.querySelector(s), icon=id=>`<svg aria-hidden="true"><use href="#${id}"/></svg>`;
const games=[
{id:'bouncykoen',name:'BouncyKoen',category:'Arcade',style:'bouncy',title:'BOUNCY<br>KOEN',image:'art/bouncy.jpg',url:'games/bouncykoen/index.html',repo:'BouncyKoen',description:'Hop through a distinctly Dutch world of busy roads, cycle lanes, canals and railway crossings. Keep Koen moving: a cheeky seagull is never far away.',controls:'Arrow keys / WASD to hop. Swipe or use the on-screen D-pad on mobile.',meta:'3D arcade · Touch & keyboard'},
{id:'conciergedienst',name:'ConciergeDienst',category:'Horror',style:'concierge',title:'CONCIERGE<br>DIENST',image:'art/concierge.jpg',url:'games/conciergedienst/index.html',repo:'Concierge-dienst',description:'You are the school caretaker on the night shift. Watch four security cameras, find the changes and report anomalies before the system is overwhelmed. Survive from midnight until 06:00.',controls:'1–4: cameras · Space / R: report · Mouse wheel: zoom · M: sound. Includes frightening images and jump scares.',meta:'Observation horror · Keyboard & mouse'},
{id:'uavpilot',name:'UAVPilot',category:'Simulation',style:'uav',title:'UAV<br>PILOT',image:'art/uav.jpg',url:'games/uavpilot/index.html',repo:'UAVPilot',description:'Take flight in a destructible, low-poly open world. Pilot eight drone tiers, navigate air defenses and unlock new equipment as you progress.',controls:'Mouse: steer · W/S: throttle · A/D: bank · V: camera · Esc: hangar. Desktop browser with WebGL 2 required.',meta:'Flight sandbox · Keyboard & mouse'},
{id:'schoolcontrol',name:'Schoolcontrol',category:'Management',style:'school',title:'SCHOOL<br>CONTROL',image:'art/school.jpg',url:null,repo:'Schoolcontrol',description:'Schoolcontrol is part of the RatelSlop collection. Its repository is currently private or unavailable. Save it to your list for when a playable build is connected.',controls:'Controls will be available when the game is connected.',meta:'Private repository · Not connected'}
];
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}function write(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{}}
let saved=read('rs-favorites',[]),recent=read('rs-recent',[]),view='discover',filter='all',detail=null,active=null,lastFocus=null;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2200)}
function render(){const search=$('#search-input').value.trim().toLowerCase();$('#game-grid').innerHTML='';const list=games.filter(g=>(view!=='favorites'||saved.includes(g.id))&&(filter==='all'||filter===g.category)&&(!$('#available').checked||g.url)&&`${g.name} ${g.category}`.toLowerCase().includes(search));for(const g of list){const card=document.createElement('article');card.className='game-card';card.innerHTML=`<button class="poster poster-${g.style}" aria-label="${g.url?'Play':'View'} ${g.name}"><img src="${g.image}" alt="" loading="lazy"><span class="badge ${g.url?'ready':''}">${g.url?'Ready to play':'Private · Not connected'}</span><span class="poster-title">${g.title}</span><span class="card-hover-play">${icon(g.url?'play':'lock')}</span></button><div class="card-text"><div><h3>${g.name}</h3><p>${g.category} · ${g.url?'Browser game':'Coming to the hub'}</p></div><button class="save iconbutton ${saved.includes(g.id)?'saved':''}" aria-label="${saved.includes(g.id)?'Remove':'Save'} ${g.name} ${saved.includes(g.id)?'from':'to'} My list" aria-pressed="${saved.includes(g.id)}">${icon('heart')}</button></div>`;card.querySelector('.poster').onclick=()=>g.url?launch(g):showDetails(g);card.querySelector('.save').onclick=()=>toggleSave(g);$('#game-grid').append(card)}$('#empty').hidden=list.length>0;$('#library-title').textContent=view==='favorites'?'My list':view==='all'?'The whole collection':search?'Search results':'Your next obsession';$('#library-subtitle').textContent=view==='favorites'?'Your favorites, ready for another round.':search?`${list.length} game${list.length===1?'':'s'} found`:'Small studio. Unreasonably good distractions.';$('.hero').hidden=view!=='discover'||!!search;$('#recent-section').hidden=!recent.length||view!=='discover'||!!search;$('#recent').innerHTML='';for(const id of recent){const g=games.find(g=>g.id===id);if(!g?.url)continue;const b=document.createElement('button');b.className='recent-item';b.innerHTML=`<img src="${g.image}" alt=""><div><strong>${g.name}</strong><span>Play again</span></div>${icon('play')}`;b.onclick=()=>launch(g);$('#recent').append(b)}}
function toggleSave(g){if(saved.includes(g.id)){saved=saved.filter(id=>id!==g.id);toast(`${g.name} removed from My list`)}else{saved.push(g.id);toast(`${g.name} added to My list`)}write('rs-favorites',saved);render();if(detail)updateDetailSave()}
function updateDetailSave(){$('#detail-save').innerHTML=icon('heart')+(saved.includes(detail.id)?'Saved to My list':'Add to My list')}
function showDetails(g){detail=g;lastFocus=document.activeElement;$('#details-art').style.backgroundImage=`linear-gradient(0deg,#0007,transparent),url('${g.image}')`;$('#details-art').innerHTML=`<span class="poster-title">${g.title}</span>`;$('#detail-category').textContent=g.category;$('#detail-title').textContent=g.name;$('#detail-description').textContent=g.description;$('#detail-controls').textContent=g.controls;$('#detail-status').textContent=g.url?'Plays here in the launcher. No installation needed.':'Private or unavailable. A playable build or hosted URL is needed to enable this game.';$('#detail-play').innerHTML=icon(g.url?'play':'lock')+(g.url?'Play now':'Not connected');$('#detail-play').disabled=!g.url;$('#source-link').href=`https://github.com/RatelSlop/${g.repo}`;updateDetailSave();$('#details').showModal()}
function launch(g){if(!g.url)return showDetails(g);if($('#details').open)$('#details').close();active=g;$('#browse').hidden=true;$('#player').hidden=false;$('footer').hidden=true;$('#player-title').textContent=g.name;$('#controls').textContent=g.controls;$('#game-frame').title=`${g.name} game`;$('#game-frame').src=g.url;recent=[g.id,...recent.filter(id=>id!==g.id)].slice(0,4);write('rs-recent',recent);window.scrollTo(0,0);$('#exit-player').focus()}
function exit(){if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});$('#game-frame').src='about:blank';$('#player').hidden=true;$('#browse').hidden=false;$('footer').hidden=false;active=null;render();$('#library-title').scrollIntoView({block:'center'});$('#hero-play').focus({preventScroll:true})}
function syncTheme(){const dark=document.documentElement.dataset.theme!=='light';$('#theme').setAttribute('aria-label',`Switch to ${dark?'light':'dark'} theme`);$('#theme').setAttribute('aria-pressed',String(!dark))}
$('#theme').onclick=()=>{const t=document.documentElement.dataset.theme==='light'?'dark':'light';document.documentElement.dataset.theme=t;try{localStorage.setItem('rs-theme',t)}catch{}syncTheme()};syncTheme();
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{if(active)exit();view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(n=>n.classList.toggle('active',n===b));render()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(n=>n.classList.toggle('selected',n===b));render()});$('#search-input').oninput=()=>{if(active)exit();render()};$('#available').onchange=render;$('#reset').onclick=()=>{view='all';filter='all';$('#search-input').value='';$('#available').checked=false;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter==='all'));document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view==='all'));render()};$('#hero-play').onclick=()=>launch(games[1]);$('#hero-details').onclick=()=>showDetails(games[1]);$('#close-details').onclick=()=>$('#details').close();$('#details').addEventListener('close',()=>{lastFocus?.focus();detail=null});$('#details').onclick=e=>{if(e.target===$('#details')){const r=$('#details').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#details').close()}};$('#detail-save').onclick=()=>toggleSave(detail);$('#detail-play').onclick=()=>launch(detail);$('#exit-player').onclick=exit;function restart(){if(active)$('#game-frame').src=active.url}$('#restart').onclick=restart;$('#retry').onclick=restart;$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#game-stage').requestFullscreen()}catch{toast('Fullscreen is unavailable in this browser')}};document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#details').open){e.preventDefault();$('#search-input').focus()}});$('.brand').onclick=e=>{e.preventDefault();if(active)exit();view='discover';$('#search-input').value='';document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view==='discover'));render();window.scrollTo(0,0)};render();
